send_js:
const ed = document.querySelector('#prompt-textarea, div[contenteditable="true"]');
if (!ed) return 'ERR:no input';
ed.focus();
document.execCommand('insertText', false, PROMPT);
await new Promise(r => setTimeout(r, 400));
const btn = document.querySelector('button[data-testid="send-button"], button[aria-label*="Send" i], button[aria-label*="Отправ" i]');
if (btn && !btn.disabled) { btn.click(); }
else {
  ed.dispatchEvent(new KeyboardEvent('keydown', {key:'Enter', code:'Enter', bubbles:true}));
  ed.dispatchEvent(new KeyboardEvent('keyup', {key:'Enter', code:'Enter', bubbles:true}));
}
return 'sent';

extract_js:
const arts = document.querySelectorAll('[data-message-author-role="assistant"], article .markdown.prose, .agent-turn');
if (!arts.length) return '';
const last = arts[arts.length - 1];
const md = last.querySelector('.markdown') || last;
return (md.innerText || '').trim();

reset_js:
const a = document.querySelector('a[href="/"], button[aria-label*="New chat" i], [data-testid*="new-chat" i]');
if (a) { a.click(); return 'reset'; }
location.href = 'https://chatgpt.com/';
return 'navigated';
